import{_ as s,C as o,o as i,c as r,a0 as t,b as l,w as n,a as d,E as c,a1 as p}from"./chunks/framework.DScjKhBS.js";const h=""+new URL("../report/agency-lifecycle-01-standard-workflow.png",import.meta.url).href,P=JSON.parse('{"title":"Standard Agency Workflow","description":"The canonical 11-phase design-and-build project flow most agencies follow, with typical timelines and deliverables.","frontmatter":{"title":"Standard Agency Workflow","description":"The canonical 11-phase design-and-build project flow most agencies follow, with typical timelines and deliverables."},"headers":[],"relativePath":"reports/agency-project-lifecycle/01-standard-workflow.md","filePath":"reports/agency-project-lifecycle/01-standard-workflow.md"}'),g={name:"reports/agency-project-lifecycle/01-standard-workflow.md"};function u(m,e,f,v,y,b){const a=o("Mermaid");return i(),r("div",null,[e[1]||(e[1]=t('<figure class="report-section-image-wrapper" aria-labelledby="fig-standard-workflow-caption"><img src="'+h+'" alt="Eleven-phase project path from estimation to post-launch support" loading="lazy" class="report-section-image"><figcaption id="fig-standard-workflow-caption">Eleven-phase project path from estimation to post-launch support</figcaption></figure><h1 id="_1-standard-agency-workflow" tabindex="-1">1. Standard Agency Workflow <a class="header-anchor" href="#_1-standard-agency-workflow" aria-label="Permalink to &quot;1. Standard Agency Workflow&quot;">​</a></h1><p>This section maps the canonical flow that most design-and-build agencies follow for a mid-sized project (8–16 weeks). Variations exist, but the phases and handoff points are broadly consistent across the industry.</p><h2 id="the-11-phase-flow" tabindex="-1">The 11-Phase Flow <a class="header-anchor" href="#the-11-phase-flow" aria-label="Permalink to &quot;The 11-Phase Flow&quot;">​</a></h2>',4)),(i(),l(p,null,{default:n(()=>[c(a,{id:"mermaid-10",class:"mermaid",graph:"flowchart%20LR%0A%20%20subgraph%20PreSale%5BPre-Sale%5D%0A%20%20%20%20EST%5B1.%20Estimation%20%26%5CnScoping%5D%0A%20%20end%0A%20%20subgraph%20Discovery%5BDiscovery%5D%0A%20%20%20%20BRIEF%5B2.%20Briefing%20%26%5CnDiscovery%5D%0A%20%20%20%20IA%5B3.%20IA%20%26%5CnContent%20Plan%5D%0A%20%20end%0A%20%20subgraph%20Design%5BDesign%5D%0A%20%20%20%20UX%5B4.%20UX%20%2F%20UI%5CnDesign%5D%0A%20%20end%0A%20%20subgraph%20Planning%5BPlanning%5D%0A%20%20%20%20SPEC%5B5.%20Technical%5CnSpec%20%26%20Plan%5D%0A%20%20end%0A%20%20subgraph%20Build%5BBuild%5D%0A%20%20%20%20DEV%5B6.%20Development%5D%0A%20%20%20%20CONTENT%5B7.%20Content%5CnPopulation%5D%0A%20%20end%0A%20%20subgraph%20QA%5BQA%20%26%20Launch%5D%0A%20%20%20%20TEST%5B8.%20QA%20%26%5CnTesting%5D%0A%20%20%20%20TRAIN%5B9.%20Client%5CnTraining%5D%0A%20%20%20%20LAUNCH%5B10.%20Delivery%5Cn%26%20Launch%5D%0A%20%20end%0A%20%20subgraph%20Post%5BPost-Launch%5D%0A%20%20%20%20SUPPORT%5B11.%20Support%20%26%5CnGovernance%5D%0A%20%20end%0A%20%20EST%20--%3E%20BRIEF%20--%3E%20IA%20--%3E%20UX%20--%3E%20SPEC%20--%3E%20DEV%20--%3E%20CONTENT%20--%3E%20TEST%20--%3E%20TRAIN%20--%3E%20LAUNCH%20--%3E%20SUPPORT%0A"})]),fallback:n(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<hr><h2 id="phase-1-estimation-and-scoping" tabindex="-1">Phase 1: Estimation and Scoping <a class="header-anchor" href="#phase-1-estimation-and-scoping" aria-label="Permalink to &quot;Phase 1: Estimation and Scoping&quot;">​</a></h2><p><strong>When:</strong> Pre-sale, before any contract is signed.</p><p><strong>What happens:</strong></p><ul><li>Account manager or sales lead receives a brief (formal or informal) from a prospect or existing client.</li><li>A senior dev/tech lead and a designer review the brief and produce a high-level estimate.</li><li>Estimate covers: hours by discipline (design, dev, PM, QA, content), timeline, assumptions, exclusions, and risks.</li><li>Output is a proposal or SOW with pricing, often T&amp;M or fixed-price.</li></ul><p><strong>Typical deliverables:</strong></p><ul><li>Proposal / SOW document</li><li>High-level sitemap or scope list</li><li>Ballpark timeline (Gantt or milestone-based)</li><li>Assumptions and exclusions register</li></ul><p><strong>Standard timeline:</strong> 2–5 days (often under time pressure; estimates are frequently done in &lt;1 day).</p><p><strong>Who is involved:</strong> Account manager, tech lead, design lead, sometimes PM.</p><hr><h2 id="phase-2-briefing-and-discovery" tabindex="-1">Phase 2: Briefing and Discovery <a class="header-anchor" href="#phase-2-briefing-and-discovery" aria-label="Permalink to &quot;Phase 2: Briefing and Discovery&quot;">​</a></h2><p><strong>When:</strong> First 1–2 weeks after contract sign-off.</p><p><strong>What happens:</strong></p><ul><li>Kickoff workshop (60–90 min) with client stakeholders: objectives, audiences, success metrics, constraints.</li><li>Audit of existing site (if redesign): content inventory, analytics review, technical audit, competitive scan.</li><li>Define measurement plan (conversion events, KPIs).</li><li>Stakeholder mapping: who approves what, and at which gate.</li><li>Output: a discovery document or brief that anchors all subsequent work.</li></ul><p><strong>Typical deliverables:</strong></p><ul><li>Discovery document (goals, audiences, constraints, risks)</li><li>Content and technical audit (for redesigns)</li><li>Competitive/category scan</li><li>Measurement plan</li><li>Stakeholder and approval matrix</li></ul><p><strong>Standard timeline:</strong> 1–2 weeks.</p><p><strong>Who is involved:</strong> PM, design lead, tech lead, client stakeholders, sometimes content strategist.</p><hr><h2 id="phase-3-information-architecture-and-content-planning" tabindex="-1">Phase 3: Information Architecture and Content Planning <a class="header-anchor" href="#phase-3-information-architecture-and-content-planning" aria-label="Permalink to &quot;Phase 3: Information Architecture and Content Planning&quot;">​</a></h2><p><strong>When:</strong> Weeks 2–4.</p><p><strong>What happens:</strong></p><ul><li>Sitemap creation: page hierarchy, navigation structure, user journeys.</li><li>Page intent definitions: what each page must communicate and what action the user should take.</li><li>Content plan: section-by-section outline per page, content sources, asset requirements (photography, video, icons, copy).</li><li>SEO alignment: keyword mapping to pages, URL structure, redirect plan (for redesigns).</li><li>Content collection begins (client provides raw copy, imagery, data).</li></ul><p><strong>Typical deliverables:</strong></p><ul><li>Sitemap (visual or spreadsheet)</li><li>Page intent / wireframe briefs</li><li>Content plan (per-page section outlines)</li><li>SEO/keyword map</li><li>Redirect plan (redesigns)</li><li>Asset requirements list</li></ul><p><strong>Standard timeline:</strong> 1–2 weeks (often overlaps with early design).</p><p><strong>Who is involved:</strong> Content strategist, UX designer, SEO specialist, PM, client content owners.</p><hr><h2 id="phase-4-ux-and-ui-design" tabindex="-1">Phase 4: UX and UI Design <a class="header-anchor" href="#phase-4-ux-and-ui-design" aria-label="Permalink to &quot;Phase 4: UX and UI Design&quot;">​</a></h2><p><strong>When:</strong> Weeks 3–7 (overlaps with IA on the front end, development on the back end).</p><p><strong>What happens:</strong></p><ul><li>Wireframes or layout studies for core templates (homepage, service page, article, listing, contact).</li><li>Component design system: cards, CTAs, forms, navigation, accordions, modals.</li><li>Visual design: brand application, typography, colour, spacing, imagery style.</li><li>Responsive behaviour defined (desktop, tablet, mobile).</li><li>Design QA: grid consistency, component states (hover, error, empty, loading), accessibility (contrast, focus).</li><li>Client review rounds (typically 2, with a change-order gate for further rounds).</li></ul><p><strong>Typical deliverables:</strong></p><ul><li>Wireframes (low-fidelity)</li><li>UI designs (high-fidelity, Figma/Sketch)</li><li>Design system / component library</li><li>Responsive specifications</li><li>Design QA checklist (states, accessibility, edge cases)</li></ul><p><strong>Standard timeline:</strong> 3–5 weeks.</p><p><strong>Who is involved:</strong> UX/UI designers, creative director, PM, client approvers.</p><hr><h2 id="phase-5-technical-specification-and-planning" tabindex="-1">Phase 5: Technical Specification and Planning <a class="header-anchor" href="#phase-5-technical-specification-and-planning" aria-label="Permalink to &quot;Phase 5: Technical Specification and Planning&quot;">​</a></h2><p><strong>When:</strong> Weeks 5–6 (starts once core design is in review; runs parallel to late-stage design).</p><p><strong>What happens:</strong></p><ul><li>Translate approved designs and content plan into a technical specification.</li><li>Define: CMS architecture (content types, fields, taxonomies), integrations (forms, CRM, analytics, search, CDN), hosting/infrastructure, performance targets.</li><li>Data model and API contracts (if headless or decoupled).</li><li>Task breakdown: tickets or spec-driven tasks for the build phase.</li><li>Identify risks, dependencies, and third-party constraints.</li></ul><p><strong>Typical deliverables:</strong></p><ul><li>Technical specification document (or <code>spec.md</code> + <code>plan.md</code> in a spec-driven workflow)</li><li>CMS architecture / content model</li><li>Integration requirements</li><li>Task breakdown (Jira tickets, <code>tasks.md</code>, or sprint plan)</li><li>Risk register</li></ul><p><strong>Standard timeline:</strong> 1–2 weeks.</p><p><strong>Who is involved:</strong> Tech lead, senior developer(s), PM, sometimes design lead for CMS/component alignment.</p><hr><h2 id="phase-6-development-build" tabindex="-1">Phase 6: Development (Build) <a class="header-anchor" href="#phase-6-development-build" aria-label="Permalink to &quot;Phase 6: Development (Build)&quot;">​</a></h2><p><strong>When:</strong> Weeks 6–11 (the largest phase by hours).</p><p><strong>What happens:</strong></p><ul><li>Environment setup: repo, CI/CD, staging, local dev tooling.</li><li>Theme/framework scaffolding.</li><li>Component build from design system (templates, blocks, partials).</li><li>CMS setup: content types, fields, custom post types, taxonomies, admin UI.</li><li>Integration work: forms, search, CRM, analytics, third-party APIs.</li><li>Performance and accessibility checks during build (not just at QA).</li><li>Regular staging deployments and internal reviews.</li></ul><p><strong>Typical deliverables:</strong></p><ul><li>Working staging site</li><li>CMS configured and ready for content entry</li><li>Integrated third-party services</li><li>Internal dev QA pass</li></ul><p><strong>Standard timeline:</strong> 4–6 weeks (varies enormously by scope).</p><p><strong>Who is involved:</strong> Developers (front-end, back-end), tech lead, PM, QA (informal during build).</p><hr><h2 id="phase-7-content-population-and-migration" tabindex="-1">Phase 7: Content Population and Migration <a class="header-anchor" href="#phase-7-content-population-and-migration" aria-label="Permalink to &quot;Phase 7: Content Population and Migration&quot;">​</a></h2><p><strong>When:</strong> Weeks 9–12 (overlaps with late build and QA).</p><p><strong>What happens:</strong></p><ul><li>Content entry into the CMS: pages, posts, media, metadata.</li><li>For redesigns: content migration from old CMS (manual, scripted, or tool-assisted).</li><li>SEO metadata entry (titles, descriptions, OG tags).</li><li>Image optimisation and alt text.</li><li>Content review by client (accuracy, tone, completeness).</li><li>Handling edge cases: legacy content, broken links, orphaned media.</li></ul><p><strong>Typical deliverables:</strong></p><ul><li>Populated staging site with real content</li><li>Migration scripts (if applicable)</li><li>Content sign-off from client</li></ul><p><strong>Standard timeline:</strong> 1–3 weeks (frequently the bottleneck — client-dependent).</p><p><strong>Who is involved:</strong> Content team (agency or client), PM, developer (for migration scripts), SEO specialist.</p><hr><h2 id="phase-8-qa-and-testing" tabindex="-1">Phase 8: QA and Testing <a class="header-anchor" href="#phase-8-qa-and-testing" aria-label="Permalink to &quot;Phase 8: QA and Testing&quot;">​</a></h2><p><strong>When:</strong> Weeks 11–13 (overlaps with content population tail).</p><p><strong>What happens:</strong></p><ul><li>Functional testing: forms, navigation, search, interactive components, CMS admin.</li><li>Cross-browser and cross-device testing.</li><li>Performance testing (Core Web Vitals, Lighthouse, load testing).</li><li>Accessibility testing (WCAG 2.2, keyboard navigation, screen reader).</li><li>Security review (dependencies, admin access, headers, input validation).</li><li>Bug triage, fix, retest cycle.</li></ul><p><strong>Typical deliverables:</strong></p><ul><li>QA report (bugs logged, severity, status)</li><li>Performance audit results</li><li>Accessibility audit results</li><li>Sign-off checklist</li></ul><p><strong>Standard timeline:</strong> 1–2 weeks.</p><p><strong>Who is involved:</strong> QA (dedicated or developer-led), PM, tech lead, client (for UAT).</p><hr><h2 id="phase-9-client-training" tabindex="-1">Phase 9: Client Training <a class="header-anchor" href="#phase-9-client-training" aria-label="Permalink to &quot;Phase 9: Client Training&quot;">​</a></h2><p><strong>When:</strong> Week 12–13 (before or at launch).</p><p><strong>What happens:</strong></p><ul><li>CMS training session(s): content editing, media management, publishing workflow.</li><li>Documentation: CMS user guide, content guidelines, component usage rules.</li><li>Admin user setup and permissions.</li><li>Walkthrough of any custom functionality or integrations.</li></ul><p><strong>Typical deliverables:</strong></p><ul><li>Training session(s) (live or recorded)</li><li>CMS user guide / documentation</li><li>Admin credentials and permission setup</li></ul><p><strong>Standard timeline:</strong> 1–3 days (often compressed).</p><p><strong>Who is involved:</strong> PM, developer or CMS specialist, client content team.</p><hr><h2 id="phase-10-delivery-and-launch" tabindex="-1">Phase 10: Delivery and Launch <a class="header-anchor" href="#phase-10-delivery-and-launch" aria-label="Permalink to &quot;Phase 10: Delivery and Launch&quot;">​</a></h2><p><strong>When:</strong> Week 13 (or agreed launch date).</p><p><strong>What happens:</strong></p><ul><li>Pre-launch checklist: DNS, SSL, redirects, analytics, sitemap submission, robots.txt, caching, CDN.</li><li>Final content review and sign-off.</li><li>Go-live (DNS switch or deployment to production).</li><li>Post-launch smoke testing: critical paths, forms, search, analytics firing.</li><li>Client notification and communication plan.</li></ul><p><strong>Typical deliverables:</strong></p><ul><li>Production site live</li><li>Launch checklist (completed)</li><li>Post-launch smoke test results</li><li>Handover documentation (hosting, credentials, support contacts)</li></ul><p><strong>Standard timeline:</strong> 1–2 days.</p><p><strong>Who is involved:</strong> Tech lead, DevOps/hosting, PM, client, account manager.</p><hr><h2 id="phase-11-post-launch-support-and-governance" tabindex="-1">Phase 11: Post-Launch Support and Governance <a class="header-anchor" href="#phase-11-post-launch-support-and-governance" aria-label="Permalink to &quot;Phase 11: Post-Launch Support and Governance&quot;">​</a></h2><p><strong>When:</strong> Ongoing after launch.</p><p><strong>What happens:</strong></p><ul><li>Hypercare period (typically 2–4 weeks): priority bug fixes, performance monitoring.</li><li>Transition to BAU support (retainer, ticket-based, or ad-hoc).</li><li>Governance: content publishing standards, component usage rules, performance monitoring, security updates.</li><li>Backlog of improvements based on real usage data (analytics, heatmaps, feedback).</li></ul><p><strong>Typical deliverables:</strong></p><ul><li>Hypercare support (defined SLA)</li><li>Governance document</li><li>Improvement backlog</li><li>Ongoing retainer or support contract</li></ul><p><strong>Standard timeline:</strong> 2–4 weeks hypercare, then ongoing.</p><p><strong>Who is involved:</strong> PM, developers, client content team, account manager.</p><hr><h2 id="typical-timeline-mid-sized-build" tabindex="-1">Typical Timeline (Mid-Sized Build) <a class="header-anchor" href="#typical-timeline-mid-sized-build" aria-label="Permalink to &quot;Typical Timeline (Mid-Sized Build)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Week</th><th>Phase</th></tr></thead><tbody><tr><td>0</td><td>Estimation and scoping (pre-sale)</td></tr><tr><td>1–2</td><td>Briefing and discovery</td></tr><tr><td>2–4</td><td>IA and content planning</td></tr><tr><td>3–7</td><td>UX/UI design</td></tr><tr><td>5–6</td><td>Technical specification</td></tr><tr><td>6–11</td><td>Development</td></tr><tr><td>9–12</td><td>Content population</td></tr><tr><td>11–13</td><td>QA and testing</td></tr><tr><td>12–13</td><td>Client training</td></tr><tr><td>13</td><td>Launch</td></tr><tr><td>13–17</td><td>Post-launch support</td></tr></tbody></table><p>Phases overlap heavily. The critical path typically runs: discovery → design → build → QA → launch. Content population is the most common external dependency and the most frequent cause of launch delays.</p>',103))])}const w=s(g,[["render",u]]);export{P as __pageData,w as default};
